export const WEAPONS={rifle:{name:'MK-I PULSE',rate:.15,damage:10,color:'#e9ffbd'},twin:{name:'TWIN REPEATER',rate:.12,damage:14,color:'#8ce9ff'},spread:{name:'SCATTER CANNON',rate:.28,damage:19,color:'#ffcf87'},rail:{name:'PIERCING RAIL',rate:.47,damage:48,color:'#caadff'},seek:{name:'SEEKER ARRAY',rate:.36,damage:30,color:'#ffacbd'},chain:{name:'ARC CONDUCTOR',rate:.24,damage:14,color:'#8affda'}};
export const REWARDS=['twin','shield','spread','repair','rail','overdrive','seek','special','chain'];
export class Battle{
 constructor({random=Math.random,event=()=>{}}={}){this.random=random;this.event=event;this.mode='ready';this.level=0;this.bestLevel=0;this.time=0;this.player={x:0,y:1.5,hp:100,shield:0};this.enemies=[];this.bullets=[];this.effects=[];this.score=0;this.kills=0;this.shots=0;this.hits=0;this.lives=3;this.specials=3;this.weapon='rifle';this.unlocked=['rifle'];this.stageTime=0;this.phase='march';this.cooldown=0;this.spawnTimer=1;this.podTimer=5;this.counter=0;this.boss=null;this.invulnerable=0;this.overdrive=0;this.transition=0;this.runMode='campaign';this.difficulty='standard';this.combo=0;this.comboTime=0;this.podCount=0;this.wave=0;}
 start({level=0,mode='campaign',difficulty='standard',weapon='rifle',unlocked=['rifle'],seed}={}){if(seed!==undefined)this.random=seeded(seed);this.level=clamp(level,0,11);this.runMode=mode;this.difficulty=difficulty;this.unlocked=[...new Set(['rifle',...unlocked])];this.weapon=this.unlocked.includes(weapon)?weapon:'rifle';this.score=0;this.kills=0;this.shots=0;this.hits=0;this.lives=mode==='arcade'?1:3;this.specials=3;this.player={x:0,y:1.5,hp:100,shield:0};this.time=0;this.mode='playing';this.podCount=0;this.setupStage();}
 setupStage(){this.stageTime=0;this.phase='march';this.enemies=[];this.bullets=[];this.boss=null;this.spawnTimer=.7;this.podTimer=3.4;this.wave=0;this.cooldown=0;this.transition=0;this.invulnerable=2;this.player.hp=Math.min(100,this.player.hp+30);this.event('stage',{level:this.level});if(this.runMode==='bossrush')this.spawnBoss();}
 get config(){return LEVELS[this.level%12];}
 get damageScale(){return this.difficulty==='recruit'?.6:this.difficulty==='veteran'?1.35:1;}
 spawn(type,x,z=-80){if(this.enemies.length>=19)return null;const hp={soldier:23,runner:35,shield:56,skeleton:18,drone:24,brute:110,pod:23,summoner:75}[type]||25;const e={id:++this.counter,type,x,y:type==='drone'?3.7:type==='pod'?3.0:1.25,z,hp,maxHp:hp,age:0,fire:1.5+this.random()*2.3,speed:type==='runner'?9.5:type==='brute'?3.1:type==='pod'?3.5:4.8+this.level*.13,phase:this.random()*6.28,alive:true,flash:0};if(type==='pod'){e.reward=REWARDS[this.podCount++%REWARDS.length];e.speed=4.2;}this.enemies.push(e);this.event('spawn',e);return e;}
 formation(){this.wave++;const types=['soldier','soldier','skeleton','runner','shield','drone','brute','summoner'];const n=3+Math.min(2,Math.floor(this.level/4));const base=(this.random()-.5)*5;for(let i=0;i<n;i++){const pick=Math.min(types.length-1,Math.floor(this.random()*(3+this.level*.55)));this.spawn(types[pick],clamp(base+(i-(n-1)/2)*2.5,-8.5,8.5),-78-Math.floor(i/3)*7);}this.event('wave',this.wave);}
 spawnBoss(){if(this.boss)return;this.phase='boss';this.enemies=this.enemies.filter(e=>e.type==='pod');const giant=this.level%2===1;const hp=giant?550+this.level*42:200+this.level*26;this.boss={id:++this.counter,type:'boss',kind:this.config.kind,name:this.config.boss,x:0,y:giant?4.3:2.0,z:-48,hp,maxHp:hp,age:0,fire:2.5,phase:1,alive:true,flash:0,giant,armor:giant?2:0};this.event('boss',this.boss);}
 hurt(amount){if(this.invulnerable>0||this.mode!=='playing'||this.transition)return;let damage=amount*this.damageScale;if(this.player.shield>0){const absorbed=Math.min(this.player.shield,damage);this.player.shield-=absorbed;damage-=absorbed;}this.player.hp=Math.max(0,this.player.hp-damage);this.invulnerable=.65;this.combo=0;this.event('hurt',amount);if(this.player.hp<=0){this.lives--;this.event('lost');if(this.lives<=0){this.mode='over';this.event('over');}else{this.player.hp=100;this.player.shield=0;this.specials=Math.max(1,this.specials);const wasBoss=this.phase==='boss';this.setupStage();if(wasBoss&&this.phase!=='boss')this.spawnBoss();}}}
 reward(type){this.score+=150;this.event('reward',type);if(WEAPONS[type]){this.weapon=type;if(!this.unlocked.includes(type)){this.unlocked.push(type);this.event('unlock',type);}}if(type==='shield')this.player.shield=Math.min(100,this.player.shield+65);if(type==='repair')this.player.hp=Math.min(100,this.player.hp+40);if(type==='special')this.specials=Math.min(6,this.specials+2);if(type==='overdrive')this.overdrive=14;}
 hit(e,damage,weak=false){if(!e?.alive)return;const amount=damage*(e.type==='boss'?(weak?1.9:.8):1);e.hp-=amount;e.flash=.1;this.hits++;this.event('impact',{x:e.x,y:e.y,z:e.z,weak,type:e.type});if(e.hp<=0){e.alive=false;if(e.type==='pod'){this.reward(e.reward);this.event('destroy',e);return;}this.combo++;this.comboTime=4;this.kills++;this.score+=(e.type==='boss'?1500:e.type==='brute'?200:70)*Math.min(5,1+Math.floor(this.combo/5));this.event('destroy',e);if(e.type==='boss'){this.bullets=[];this.transition=3;this.phase='clear';this.event('clear',{level:this.level,score:this.score});}}}
 shoot(targetId=null,weak=false){if(this.mode!=='playing'||this.transition||this.cooldown>0)return;const w=WEAPONS[this.weapon];this.cooldown=w.rate*(this.overdrive>0?.55:1);this.shots++;const all=[...this.enemies,...(this.boss?[this.boss]:[])];let e=all.find(e=>e.id===targetId&&e.alive);if(this.weapon==='seek'&&!e)e=all.filter(e=>e.alive&&e.type!=='pod').sort((a,b)=>b.z-a.z)[0];this.event('shot',{target:e?{x:e.x,y:e.y,z:e.z}:null,weapon:this.weapon});if(e){this.hit(e,w.damage,weak);if(['spread','chain','rail'].includes(this.weapon))for(const other of all){if(other===e||!other.alive||other.type==='pod')continue;const dist=Math.hypot(other.x-e.x,(other.z-e.z)*.15);if(dist<(this.weapon==='chain'?5:this.weapon==='spread'?3:1.5))this.hit(other,w.damage*.6);}}
 }
 special(){if(this.mode!=='playing'||this.transition||this.specials<=0)return false;this.specials--;this.bullets=[];for(const e of this.enemies)if(e.type!=='pod')this.hit(e,95);if(this.boss)this.hit(this.boss,180,true);this.invulnerable=Math.max(this.invulnerable,1);this.event('special');return true;}
 pause(){if(this.mode==='playing'){this.mode='paused';return true;}return false;}
 resume(){if(this.mode==='paused')this.mode='playing';}
 enemyFire(e,spread=0){const base=Math.atan2(this.player.x-e.x,6-e.z);for(let i=-spread;i<=spread;i++){const angle=base+i*.15,speed=15+this.level*.7;const dx=Math.sin(angle)*speed,dz=Math.cos(angle)*speed;const travel=(6-e.z)/Math.max(1,dz),dy=(this.player.y-e.y)/travel;this.bullets.push({id:++this.counter,x:e.x,y:e.y,z:e.z,vx:dx,vy:dy,vz:dz,r:e.type==='boss'?.24:.13});}this.event('enemyfire',e);}
 step(dt,input={}){if(this.mode!=='playing')return;dt=clamp(dt,0,.04);this.time+=dt;this.invulnerable=Math.max(0,this.invulnerable-dt);this.cooldown-=dt;this.overdrive=Math.max(0,this.overdrive-dt);this.comboTime-=dt;if(this.comboTime<=0)this.combo=0;
 const targetX=input.x??this.player.x,targetY=input.y??this.player.y;this.player.x+=clamp(targetX-this.player.x,-19*dt,19*dt);this.player.x=clamp(this.player.x,-7.5,7.5);this.player.y=clamp(this.player.y+clamp(targetY-this.player.y,-8*dt,8*dt),.9,4.1);
 if(this.transition>0){this.transition-=dt;if(this.transition<=0){if(this.level>=11&&this.runMode!=='survival'){this.mode='won';this.event('won');}else{this.level=this.runMode==='bossrush'?this.level+2:this.level+1;if(this.level>11)this.level=0;this.setupStage();}}return;}
 this.stageTime+=dt;if(input.fire)this.shoot(input.targetId,input.weak);if(input.special)this.special();
 if(this.phase==='march'){this.spawnTimer-=dt;if(this.spawnTimer<=0){this.formation();this.spawnTimer=Math.max(3.2,6-this.level*.2);}if(this.stageTime>72)this.spawnBoss();}
 this.podTimer-=dt;if(this.podTimer<=0){this.spawn('pod',(this.random()-.5)*11,-55);this.podTimer=this.phase==='boss'?12:10;}
 for(const e of this.enemies){if(!e.alive)continue;e.age+=dt;e.flash=Math.max(0,e.flash-dt);e.z+=e.speed*dt;if(e.type==='pod'){e.y=3+Math.sin(e.age*1.5)*.65;e.x+=Math.sin(e.age+e.phase)*dt*.7;}if(e.type==='drone')e.x+=Math.sin(e.age*2+e.phase)*dt*2.4;e.fire-=dt;if(e.type!=='pod'&&e.z<-5&&e.z>-68&&e.fire<=0){this.enemyFire(e,e.type==='brute'?1:0);e.fire=(e.type==='runner'?5:3)+this.random()*2;if(e.type==='summoner'&&this.enemies.length<15)this.spawn('skeleton',e.x+1.5,e.z-3);}if(e.z>7){e.alive=false;if(e.type!=='pod')this.hurt(e.type==='runner'?17:11);}}
 this.enemies=this.enemies.filter(e=>e.alive);
 if(this.boss?.alive){const b=this.boss;b.age+=dt;b.z=Math.min(-21,b.z+3*dt);b.x=Math.sin(b.age*.48)*(b.giant?3.2:5.5);b.flash=Math.max(0,b.flash-dt);b.phase=b.hp/b.maxHp>.66?1:b.hp/b.maxHp>.33?2:3;b.fire-=dt;if(b.fire<=0){this.enemyFire(b,b.phase);b.fire=Math.max(.8,2.6-b.phase*.35);this.event('bossattack',b);if(b.phase>1&&this.enemies.length<8)this.spawn(this.level>6?'runner':'soldier',b.x+(this.random()-.5)*6,-45);}}
 for(const b of this.bullets){const oldZ=b.z;b.x+=b.vx*dt;b.y+=b.vy*dt;b.z+=b.vz*dt;if(oldZ<=6&&b.z>=5.5&&Math.abs(b.x-this.player.x)<.75+b.r&&Math.abs(b.y-this.player.y)<.75+b.r){b.dead=true;this.hurt(14);}}
 this.bullets=this.bullets.filter(b=>!b.dead&&b.z<14&&Math.abs(b.x)<25&&b.y>-4&&b.y<15).slice(-120);
 }
}
